Here's a C++ function that takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` containing HTML formatted text:

```cpp
#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex re(R"(^```)(.*?)(.*?```)");
    std::smatch match;
    while (std::regex_search(html, match, re)) {
        html = match[1] + "<code>" + match[2] + "</code>" + match[3];
    }
    return html;
}

int main() {
    std::string markdown = "```cpp\nint main() {\n    std::cout << \"Hello, World!\" << std::endl;\n}\n```";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses a regular expression to find all Markdown code blocks (enclosed in backticks) and replaces them with HTML `<code>` tags. The regular expression `"(^```)(.*?)(.*?```)"` matches the pattern of Markdown code blocks and captures the text between the backticks.

